+      // Dies ist wichtig, wenn der Benutzer auf Tage aus Neben-Monaten klickt
+      final dateToLoad = _selectedDay ?? _focusedDay;
+      
+      print('Loading releases for: ${dateToLoad.day}.${dateToLoad.month}.${dateToLoad.year} (focused: ${_focusedDay.day}.${_focusedDay.month}.${_focusedDay.year})');
+      
+      final releases = await _crunchyrollService.getReleasesForWeek(
+        dateToLoad,
+      );
+
+      final Map<DateTime, List<AnimeRelease>> releasesByDay = {};
+      for (var release in releases) {
+        final date = DateTime(
+          release.releaseTime.year,
+          release.releaseTime.month,
+          release.releaseTime.day,
+        );
+
+        if (releasesByDay[date] == null) {
+          releasesByDay[date] = [];
+        }
+        releasesByDay[date]!.add(release);
+      }
+
+      setState(() {
+        _releases = releasesByDay;
+        _isLoading = false;
+      });
+    } catch (e) {
+      print('Error loading releases: $e');
+      setState(() {
+        _isLoading = false;
