+    if (_debugPrint) print('🧊 Freeze check: monthStart=${monthStart.month}/${monthStart.year}, twoMonthsAgo=${twoMonthsAgo.month}/${twoMonthsAgo.year}, isBefore=${monthStart.isBefore(twoMonthsAgo)}');
+    
+    if (monthStart.isBefore(twoMonthsAgo)) {
+      // Monat ist eingeforen - Refresh nicht erlaubt
+      _showFrozenMonthMessage();
+      return;
+    }
