+  Future<void> _loadDescription() async {
+    final description = await widget.crunchyrollService.fetchDescription(
+      widget.release,
+    );
+    if (mounted) {
+      setState(() {
+        _descriptionOriginal = description;
+        _isLoadingDescription = false;
