+  Future<void> _translateDescription() async {
+    if (_descriptionOriginal == null || 
+        _descriptionOriginal == 'Keine Beschreibung verfügbar' ||
+        _descriptionTranslated != null) {
+      return;
+    }
+    
+    setState(() {
+      _isTranslating = true;
