+  Future<void> _loadReleases() async {
+    // Lade beim Start alle gecachten Daten (Bilder, verarbeitete Titel) - nur einmal
+    if (!_cacheLoaded) {
+      await _crunchyrollService.loadCacheOnStartup();
+      _cacheLoaded = true;
+    }
+    
+    setState(() {
+      _isLoading = true;
