+        !(month == currentMonth || 
+          month == previousMonth || 
+          month == nextMonth)
+      ).toList();
+      
+      if (kDebugMode) print('Loading ${otherMonths.length} additional months sequentially...');
+      
+      // Lade nacheinander SEQUENZIELL, nicht parallel
